INSERT IGNORE INTO content_pages
  (content_item_id, standfirst_en, standfirst_ur, body_en, body_ur,
   hero_image_id)
SELECT ci.id, NULL, NULL, NULL, NULL, NULL
  FROM content_items ci
 WHERE ci.content_type = 'page'
   AND ci.slug IN ('advocacy', 'advocacy-positions', 'advocacy-budget-proposals', 'advocacy-economy', 'advocacy-research', 'advocacy-business-confidence');

-- advocacy-research  (/advocacy/research)
--   from https://lcci.com.pk/about.php?id=113 (101 chars)
--   2 document(s) still hosted on the old server
--   and linked absolutely. They have to be moved before the old host goes.
--   2 link(s) to the old site that this
--   migration has no new address for, left as written. Each one needs
--   either a route or a redirect before the old host is switched off:
--     http://lcci.com.pk/LCN/LCN_Dec_24_Jan_25.pdf
--     http://lcci.com.pk/LCN/LCN_October_24.pdf
UPDATE content_pages p
  JOIN content_items ci ON ci.id = p.content_item_id
   SET p.body_en = '<h2>Lahore Chamber Newsletter</h2><ul>
	<li>
	<h3><a href="http://lcci.com.pk/LCN/LCN_Dec_24_Jan_25.pdf"><strong>Lahore Chamber News (LCN) December - 2024 - January - 2025 </strong></a></h3>
	</li>
	<li>
	<h3><a href="http://lcci.com.pk/LCN/LCN_October_24.pdf"><strong>Lahore Chamber News (LCN) October - 2024</strong></a></h3>
	</li>
</ul>

<p><strong>​</strong></p>'
 WHERE ci.content_type = 'page'
   AND ci.slug = 'advocacy-research'
   AND p.body_en IS NULL;

UPDATE content_items
   SET status = 'published', published_at = '2026-10-01 05:00:00.000'
 WHERE content_type = 'page' AND slug = 'advocacy-research'
   AND status = 'draft'
   AND EXISTS (
     SELECT 1 FROM content_pages p
      WHERE p.content_item_id = content_items.id AND p.body_en IS NOT NULL
   );

